        fn fixture() -> Game<'static> {
            adapter::fixture_reset();
            sunset::GUI.store(false, Ordering::SeqCst);
            ui::SETTINGS_CALLS.store(0, Ordering::SeqCst);
            ui::SNAPSHOT_CALLS.store(0, Ordering::SeqCst);
            let config = Config { profiles: vec![Profile {
                id: "fixture".into(), addresses: vec!["fixture.invalid:25565".into()],
                players: vec!["Alice".into()], command: "msg".into(),
            }] };
            assert!(config.validate().is_ok());
            ui::with(|ui| {
                ui.state = Some(ui::State { selection: "auto".into(), config: Arc::new(config), generation: 1, load_error: None });
                ui.module = Some(ui::Module { on: true, tab: true, completion: true });
            });
            Game {
                window: true, native_enabled: true, playing: true, focused: true,
                remote: Some(Remote { logged_in: true }), player: Some(()),
                integrated: None,
                snapshot: Some(FixtureSnapshot { roster: Vec::new(), nearby: Vec::new(), local: [0.0; 3] }),
                packets: Vec::new(), messages: Vec::new(), marker: PhantomData,
            }
        }
        fn connect(game: &Game<'_>) { adapter::connecting(game, "fixture.invalid:25565", false); }
        fn request(game: &mut Game<'_>) -> i32 {
            connect(game);
            adapter::frame(game);
            assert_eq!(game.packets.len(), 1);
            let (packet, data) = &game.packets[0];
            assert_eq!(*packet, horizon_protocol::ids::play::serverbound::COMMAND_SUGGESTION);
            let mut reader = Reader::new(data);
            let id = reader.varint().unwrap();
            assert_eq!(id, wire::FIRST_ID);
            assert!(id < 0);
            assert_eq!(reader.string(64).unwrap(), "/msg alice");
            assert_eq!(reader.remaining(), 0);
            id
        }
        fn reply(id: i32, start: i32, length: i32, names: &[&str]) -> Vec<u8> {
            let mut writer = Writer::new();
            writer.varint(id); writer.varint(start); writer.varint(length); writer.varint(names.len() as i32);
            for name in names { writer.string(name); writer.bool(false); }
            writer.data
        }
        fn assert_no_packets(game: &Game<'_>) { assert!(game.packets.is_empty()); assert!(game.messages.is_empty()); }

