        #[test]
        fn current_owned_reply_cancels_immediately_when_native_context_disappears_between_frames() {
            for mode in 0..4 {
                let mut game = fixture(); let id = request(&mut game);
                let saved_snapshot = game.snapshot.clone();
                match mode {
                    0 => game.native_enabled = false,
                    1 => game.window = false,
                    2 => game.snapshot = None,
                    _ => game.integrated = Some(()),
                }
                // No frame runs between changing the context and receiving this reply.
                assert!(adapter::suggestions(&mut game, &reply(id, 5, 5, &["Alice"])));
                assert!(game.messages.is_empty());
                game.native_enabled = true; game.window = true;
                game.snapshot = saved_snapshot; game.integrated = None;
                let calls = ui::SETTINGS_CALLS.load(Ordering::SeqCst);
                let snapshots = ui::SNAPSHOT_CALLS.load(Ordering::SeqCst);
                // Restoring the context must not revive the old request or do expensive UI work.
                assert!(adapter::suggestions(&mut game, &reply(id, 5, 5, &["Alice"])));
                assert!(game.messages.is_empty());
                assert_eq!(ui::SETTINGS_CALLS.load(Ordering::SeqCst), calls);
                assert_eq!(ui::SNAPSHOT_CALLS.load(Ordering::SeqCst), snapshots);
            }
        }

