        #[test]
        fn announcement_coalesces_renamed_uuid_and_unresolved_name_case_independently() {
            use sunset_watch_state::{Alert, Evidence};
            let mut game = fixture();
            adapter::fixture_announce(&mut game, vec![
                Alert { name: "Alice".into(), uuid: Some(1), evidence: Evidence::HiddenFromTab },
                Alert { name: "Alicia".into(), uuid: Some(1), evidence: Evidence::NearbyEntity },
                Alert { name: "Bob".into(), uuid: Some(2), evidence: Evidence::SuggestedOffTab },
                Alert { name: "Charlie".into(), uuid: None, evidence: Evidence::TabDisappearance },
                Alert { name: "CHARLIE".into(), uuid: None, evidence: Evidence::HiddenFromTab },
            ]);
            assert_eq!(game.messages.len(), 3);
            assert!(game.messages.contains(&"Watch Alicia: Nearby entity while off TAB.".to_owned()));
            assert!(game.messages.contains(&"Watch Bob: Possibly online: suggested while off TAB.".to_owned()));
            assert!(game.messages.contains(&"Watch CHARLIE: Hidden from TAB.".to_owned()));
        }

